INSERT INTO `glossaries` (`id`, `term`, `definition`, `source_url`, `verification_status`, `verified_by`, `created_at`, `updated_at`) VALUES
(1, 'Saham', 'Saham adalah bukti kepemilikan atas suatu perusahaan yang memberikan hak kepada pemegangnya sesuai ketentuan yang berlaku.', 'https://idxislamic.idx.co.id/edukasi-pasar-modal-syariah/glosarium-pasar-modal-syariah/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(2, 'Investor', 'Investor adalah pihak yang menanamkan dana pada instrumen keuangan dengan tujuan memperoleh keuntungan di masa depan.', 'https://idxislamic.idx.co.id/edukasi-pasar-modal-syariah/glosarium-pasar-modal-syariah/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(3, 'Emiten', 'Emiten adalah pihak atau perusahaan yang menawarkan efek kepada masyarakat melalui pasar modal.', 'https://idxislamic.idx.co.id/edukasi-pasar-modal-syariah/glosarium-pasar-modal-syariah/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(4, 'Bursa Efek', 'Bursa efek adalah pihak yang menyelenggarakan dan menyediakan sistem serta sarana untuk mempertemukan penawaran jual dan beli efek.', 'https://idxislamic.idx.co.id/edukasi-pasar-modal-syariah/glosarium-pasar-modal-syariah/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(5, 'Broker', 'Broker adalah perantara yang membantu investor melakukan transaksi jual beli efek di pasar modal.', 'https://ajaib.co.id/kamus/b/broker', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(6, 'Sekuritas', 'Sekuritas adalah perusahaan efek yang menyediakan layanan transaksi dan aktivitas terkait investasi di pasar modal.', 'https://idxislamic.idx.co.id/edukasi-pasar-modal-syariah/glosarium-pasar-modal-syariah/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(7, 'EPS', 'EPS atau earnings per share adalah laba bersih per lembar saham yang menunjukkan keuntungan perusahaan untuk setiap saham beredar.', 'https://www.idx.co.id/id/investor/stock-screener-column-explanation/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(8, 'PER', 'PER atau price to earnings ratio adalah rasio yang membandingkan harga saham dengan laba per saham.', 'https://www.idx.co.id/id/investor/stock-screener-column-explanation/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(9, 'PBV', 'PBV atau price to book value adalah rasio yang membandingkan harga saham dengan nilai buku per saham.', 'https://www.idx.co.id/id/investor/stock-screener-column-explanation/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(10, 'ROE', 'ROE atau return on equity adalah rasio yang menunjukkan kemampuan perusahaan menghasilkan laba dari modal sendiri.', 'https://www.idx.co.id/id/investor/stock-screener-column-explanation/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(11, 'IHSG', 'IHSG adalah indeks yang menggambarkan pergerakan harga seluruh saham yang tercatat di bursa sesuai metodologi yang berlaku.', 'https://idxislamic.idx.co.id/edukasi-pasar-modal-syariah/glosarium-pasar-modal-syariah/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51'),
(12, 'Indeks LQ45', 'Indeks LQ45 adalah indeks yang berisi saham-saham dengan likuiditas tinggi dan kapitalisasi pasar besar sesuai kriteria tertentu.', 'https://www.idx.co.id/id/produk/indeks/', 'literature_based', NULL, '2026-06-16 22:04:51', '2026-06-16 22:04:51');

