INSERT INTO `stock_profiles` (`id`, `stock_id`, `long_name`, `short_name`, `sector`, `industry`, `long_business_summary`, `website`, `city`, `country`, `created_at`, `updated_at`) VALUES
(1, 1, 'PT Bank Central Asia Tbk', 'Bank Central Asia Tbk', 'Financial Services', 'Banks - Regional', 'PT Bank Central Asia Tbk menyediakan perbankan komersial dan jasa keuangan lainnya. Perusahaan menawarkan deposito berjangka, deposito elektronik, pemintalan, rekening Dana Lander, rekening pelanggan, tahap emas; pinjaman, seperti kredit usaha, kredit investasi, agunan surat berharga, usaha multiguna, pembiayaan perdagangan, pinjaman tempat usaha; kartu kredit; dan investasi, termasuk reksa dana, serta obligasi dan SBN sekunder. Perusahaan juga menyediakan layanan pembukaan rekening penagihan, remittance, trade finance, treasury dan kustodian, transaksi perbankan, perbankan elektronik, cash management, bank assurance, fasilitas kredit, bank garansi, fasilitas ekspor-impor, dan fasilitas valuta asing. Selain itu, perusahaan menawarkan pembiayaan investasi, pembiayaan modal kerja, pembiayaan multiguna, sewa operasi, dan kegiatan pembiayaan lainnya; perbankan syariah; perantara perantara efek dan penjamin emisi efek; asuransi umum atau kerugian; asuransi jiwa; dan jasa modal ventura. PT Bank Central Asia Tbk didirikan pada tahun 1955 dan berkantor pusat di Jakarta, Indonesia. PT Bank Central Asia Tbk merupakan anak perusahaan PT Dwimuria Investama Andalan.', 'https://www.bca.co.id', 'Jakarta', 'Indonesia', '2026-04-20 05:20:40', '2026-04-20 05:20:40'),
(2, 3, 'PT Bank Rakyat Indonesia (Persero) Tbk', 'Bank Rakyat Indonesia (Persero)', 'Financial Services', 'Banks - Regional', 'PT Bank Rakyat Indonesia (Persero) Tbk menyediakan berbagai produk dan layanan perbankan di Indonesia dan internasional. Perusahaan menawarkan tabungan dan giro; waktu, waktu mata uang asing, dan simpanan on-call; pinjaman hipotek, modal kerja, investasi, waralaba, dan agunan tunai, serta pembiayaan rantai pasokan dan nilai serta jaminan bank; dan mikrofon, kecil dan menengah, dan pinjaman program. Ini juga menyediakan pembayaran tagihan, deposito, transaksi online, pengiriman uang, transfer uang, bisnis, keuangan, institusi, perbendaharaan dan global, kustodian, wali amanat, dan layanan pengelolaan kas. Selain itu, perusahaan menawarkan produk dan layanan investasi; jasa dan pembiayaan perdagangan, dan jasa perbankan transaksi, termasuk impor dan ekspor, standby L/C, money changer, layanan sistem online BRI RTE, serta letter of credit; kartu kredit; dan manajemen kekayaan, pedagang, dan layanan perbankan digital. Selain itu, perusahaan ini juga menyediakan asuransi jiwa dan umum, penjaminan dan perantara efek, serta layanan modal ventura. PT Bank Rakyat Indonesia (Persero) Tbk didirikan pada tahun 1895 dan berkantor pusat di Jakarta, Indonesia.', 'https://bri.co.id', 'Jakarta', 'Indonesia', '2026-04-20 05:21:00', '2026-04-20 05:21:00'),
(3, 4, 'PT Bank Mandiri (Persero) Tbk', 'Bank Mandiri (Persero) Tbk', 'Financial Services', 'Banks - Regional', 'PT Bank Mandiri (Persero) Tbk menyediakan berbagai produk dan layanan perbankan kepada individu dan bisnis di Indonesia, Singapura, Malaysia, Hong Kong, Timor Leste, Shanghai, Inggris, dan Kepulauan Cayman. Ia menawarkan rekening tabungan dan giro, multicurrency, payroll, SEKARANG, dan rekening tabungan mata uang asing; kredit perseorangan, hipotek, usaha mikro, kecil dan menengah, modal kerja, dan investasi; kartu perusahaan, kredit, dan debit; dan layanan perbankan elektronik. Perusahaan juga menyediakan produk asuransi jiwa, kesehatan, dan kecelakaan, serta produk investasi; pengelolaan kas, pengumpulan tagihan, pembayaran, pembiayaan perdagangan, transfer uang, pengiriman uang, dan layanan pengelolaan kekayaan; dan layanan treasury, termasuk transaksi tunai, lindung nilai, dan produk investasi. Perusahaan ini mengoperasikan kantor cabang, kantor cabang pembantu, dan kantor cabang luar negeri; dan fasilitas ATM. Perusahaan ini didirikan pada tahun 1998 dan berkantor pusat di Jakarta, Indonesia.', 'https://bankmandiri.co.id', 'Jakarta', 'Indonesia', '2026-04-20 05:21:15', '2026-04-20 05:21:15'),
(4, 5, 'PT Humpuss Maritim Internasional Tbk', 'Humpuss Maritim Internasional T', 'Industrials', 'Marine Shipping', 'PT Humpuss Maritim Internasional Tbk., bersama anak perusahaannya, mengangkut gas alam cair, minyak mentah, bahan bakar minyak, bahan kimia, kontainer, batu bara, dan kargo laut lainnya di Indonesia. Perusahaan ini beroperasi di Kapal Chartered; dan segmen Awak Kapal dan Jasa Manajemen. Perusahaan ini juga terlibat dalam transportasi LNG, transportasi minyak dan petrokimia, dukungan kelautan, kapal pendukung lepas pantai, manajemen kapal, manajemen kru, dan layanan pelatihan kru. Perusahaan ini didirikan pada tahun 1986 dan berkantor pusat di Jakarta, Indonesia. PT Humpuss Maritim Internasional Tbk beroperasi sebagai anak perusahaan dari PT Humpuss Intermoda Transportasi Tbk.', 'https://www.humi.co.id', 'Jakarta', 'Indonesia', '2026-04-20 05:21:24', '2026-04-20 05:21:24'),
(5, 6, 'PT Barito Pacific Tbk', 'Barito Pacific Tbk.', 'Basic Materials', 'Chemicals', 'PT Barito Pacific Tbk bersama anak perusahaannya bergerak dalam bidang usaha produksi petrokimia. Perusahaan ini beroperasi melalui segmen Petrokimia, Manajemen Bangunan dan Hotel (Properti), Energi dan Sumber Daya, dan Lainnya. Perusahaan memproduksi palet olefin, poliolefin, stirena monomer, dan butadiena, termasuk produk sampingannya. Perusahaan ini juga mengoperasikan proyek sumber daya energi panas bumi dan pembangkit listrik tenaga angin. Selain itu, perusahaan terlibat dalam pengembangan dan pembangunan properti industri dan komersial; transportasi laut; logistik; dan produksi lem untuk papan partikel. Selanjutnya, ia menyediakan layanan konsultasi manajemen. Perusahaan ini sebelumnya bernama PT Barito Pacific Timber Tbk dan berganti nama menjadi PT Barito Pacific Tbk pada tahun 2007. PT Barito Pacific Tbk didirikan pada tahun 1979 dan berkantor pusat di Jakarta, Indonesia.', 'https://www.barito-pacific.com', 'Jakarta', 'Indonesia', '2026-04-20 05:21:32', '2026-04-20 05:21:32'),
(8, 9, 'PT Bank Negara Indonesia (Persero) Tbk', 'Bank Negara Indonesia  (Persero', 'Financial Services', 'Banks - Regional', 'PT Bank Negara Indonesia (Persero) Tbk bersama anak perusahaannya menyediakan berbagai produk dan layanan perbankan di Indonesia, negara-negara Asia lainnya, New York, dan Eropa. Ini beroperasi melalui segmen Perbankan Korporasi, Perbankan Institusional, Perbankan Komersial, Perbankan Konsumer, Perbankan Treasury & Internasional, Kantor Pusat, dan Anak Perusahaan. Perusahaan menawarkan penghematan; rencana tabungan dan produk FIPF; pinjaman; kartu kredit; layanan bancassurance, penggajian, dan simulasi; brankas, referensi bank, obligasi, uang kertas asing, dan layanan mobile banking; layanan untuk menagih pembayaran atau dokumen berharga; dan Xpora, solusi digital untuk usaha kecil dan menengah. Ia juga menyediakan perbankan bisnis, pendanaan, pinjaman, pembiayaan perdagangan, pengiriman uang cerdas, investasi asing langsung, manajemen pengumpulan dan likuiditas, manajemen pembayaran, pembiayaan rantai pasokan, pembiayaan konsumen, manajemen kekayaan, dan layanan kustodi dan perwalian; produk lembaga keuangan; solusi bagi sektor industri; dan produk Treasury. Selain itu, perusahaan menawarkan layanan asuransi dan modal ventura; surat berharga; dan layanan ATM, perbankan telepon dan SMS, perbankan seluler dan internet, serta gateway pembayaran internet. PT Bank Negara Indonesia (Persero) Tbk didirikan pada tahun 1946 dan berkantor pusat di Jakarta Pusat, Indonesia.', 'https://www.bni.co.id', 'Jakarta Pusat', 'Indonesia', '2026-05-28 12:57:06', '2026-05-28 12:57:06'),
(9, 10, 'PT Indofood Sukses Makmur Tbk', 'Indofood Sukses Makmur Tbk', 'Consumer Defensive', 'Packaged Foods', 'PT Indofood Sukses Makmur Tbk beroperasi sebagai perusahaan solusi makanan di Indonesia, seluruh Asia, Afrika, dan internasional. Perusahaan beroperasi melalui segmen Kelompok Usaha Produk Bermerek Konsumen, Kelompok Usaha Bogasari, Kelompok Agribisnis, dan Kelompok Usaha Distribusi. Perusahaan ini menyediakan produk-produk bermerek konsumen, seperti mie, produk susu, makanan ringan, penyedap makanan, nutrisi dan makanan khusus, serta minuman. Perusahaan juga menawarkan produk kemasan yang fleksibel dan bergelombang; dan memproduksi serta menjual tepung terigu dan pasta. Selain itu, perusahaan ini juga bergerak dalam bidang pemuliaan benih serta budidaya dan penggilingan kelapa sawit; manufaktur dan pemasaran minyak goreng, margarin, dan produk mentega; dan budidaya tebu, karet, dan tanaman lainnya, serta mendistribusikan produk konsumsi yang diproduksi oleh pihak ketiga. Perusahaan ini sebelumnya bernama PT Panganjaya Intikusuma dan berubah nama menjadi PT Indofood Sukses Makmur Tbk pada Januari 1994. Perusahaan ini didirikan pada tahun 1990 dan berkantor pusat di Jakarta, Indonesia. PT Indofood Sukses Makmur Tbk beroperasi sebagai anak perusahaan First Pacific Investment Management Limited.', 'https://www.indofood.com', 'Jakarta', 'Indonesia', '2026-05-28 13:02:52', '2026-05-28 13:02:52');

